/** Pipe text preserves empty cells; plain text uses whitespace-separated words. */
export function splitCells(text: string): string[] {
  const trimmed = text.trim()
  return trimmed
    ? trimmed.includes('|')
      ? trimmed.split('|').map((cell) => cell.trim())
      : words(trimmed)
